    PgmIo.write("components.txt", componentReport());
    PgmIo.write("report.txt", report());
}
static int rho(PgmIo.Point p, int t, int[][] trig, int step) {
    return Math.floorDiv(p.x() * trig[t][0] + p.y() * trig[t][1], 16384 * step);
}
